<template><section class="scb-workspace-panel"><h2>Plot Twist Co × MH4Kidz</h2><p>{{commercial.active?'Executed terms recorded':'Unsigned proposed terms'}} · Revision {{commercial.revision}}</p><p>The development period runs {{draft.rolloutDate}} through {{commercial.terms.developmentEndDate}}. Free customer offers still incur the platform percentage of standard usage value.</p><div class="scb-actions"><button v-for="doc in commercial.documents" :key="doc.key" class="scb-button scb-outline" @click="$emit('download',doc.key)">Print / save {{doc.key==='baa'?'BAA':doc.key==='platform-agreement'?'platform contract':'presenter contract'}}</button></div><form class="scb-form scb-ops-form" @submit.prevent="save"><fieldset :disabled="!platformAdmin||commercial.active||busy"><legend>Agreement details</legend><div class="scb-ops-grid"><label v-for="[key,label] in textFields" :key="key">{{label}}<input v-model="draft[key]" :type="key.includes('Email')?'email':key.includes('Date')?'date':'text'"/></label><label>MH4Kidz HIPAA role<select v-model="draft.operatorHipaaRole"><option value="business_associate">Business associate (Plot Twist is subcontractor)</option><option value="covered_entity">Covered entity (Plot Twist is business associate)</option></select></label></div><label>Upstream covered entities and data/services scope<textarea v-model="draft.upstreamCoveredEntities" rows="3"/></label><div class="scb-ops-grid"><label v-for="[key,label] in rates" :key="key">{{label}}<input v-model="displayRates[key]" type="number" min="0" step="0.01" :max="key.endsWith('Bps')?100:undefined"/></label><label>Invoice due in days<input v-model.number="draft.paymentDueDays" type="number" min="1" max="90"/></label></div><button v-if="platformAdmin&&!commercial.active" class="scb-button">Save proposed terms</button></fieldset></form><p>Complete all blanks and obtain legal and independent organizational approval before signing. Signed paper copies can be uploaded in MH4Kidz FundThred as contract documents.</p><form v-if="platformAdmin&&!commercial.active" class="scb-form" @submit.prevent="$emit('activate',{...activation,revision:commercial.revision,reviewHash:commercial.reviewHash})"><h3>Record execution</h3><label>Signed platform contract<select v-model="activation.contractDocumentId" required><option value="">Choose uploaded PDF</option><option v-for="d in evidence" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>Signed BAA<select v-model="activation.baaDocumentId" required><option value="">Choose uploaded PDF</option><option v-for="d in evidence" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="scb-ops-check"><input v-model="activation.signedTermsReviewed" type="checkbox" required/> Both parties signed the displayed revision, with all blanks completed and no unrecorded changes.</label><label class="scb-ops-check"><input v-model="activation.independentApprovalConfirmed" type="checkbox" required/> Required independent approval and conflict disclosures have been documented.</label><button class="scb-button" :disabled="busy">Record signed agreement and enable contracted billing</button></form></section></template>
<script setup>
import {ref} from 'vue';
const props=defineProps({commercial:Object,evidence:Array,platformAdmin:Boolean,busy:Boolean}),emit=defineEmits(['save','download','activate']);
const draft=ref({...props.commercial.terms}),activation=ref({contractDocumentId:'',baaDocumentId:'',signedTermsReviewed:false,independentApprovalConfirmed:false});
const textFields=[['operatorLegalName','MH4Kidz legal entity'],['platformLegalName','Plot Twist Co legal entity'],['operatorAddress','MH4Kidz legal address'],['platformAddress','Plot Twist Co legal address'],['operatorNoticeEmail','MH4Kidz notice email'],['platformNoticeEmail','Plot Twist Co notice email'],['governingState','Governing state'],['effectiveDate','Agreement effective date'],['rolloutDate','Rollout date']];
const rates=[['schoolMonthlyCents','School monthly standard price (USD)'],['providerMonthlyCents','Provider slot monthly standard price (USD)'],['adminMonthlyCents','Admin slot monthly standard price (USD)'],['developmentBps','Platform usage share: first 12 months (%)'],['ongoingBps','Platform usage share: thereafter (%)'],['bookingPlatformBps','Workshop platform share (%)'],['bookingOperatorBps','Workshop MH4Kidz share (%)']];
const displayRates=ref(Object.fromEntries(rates.map(([k])=>[k,draft.value[k]==null?'':draft.value[k]/100])));
function save(){emit('save',{revision:props.commercial.revision,terms:{...draft.value,...Object.fromEntries(rates.map(([k])=>[k,displayRates.value[k]===''?null:Math.round(Number(displayRates.value[k])*100)]))}});}
</script>
